initJs:
function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let timerInterval = null;
  let pauseStartTime = null;
  let totalPauseTime = 0;

  // 現在時刻表示の更新
  function updateCurrentTime() {
    const now = new Date();
    container.querySelector('#current-time').textContent = now.toLocaleString('ja-JP');
  }

  // 経過時間表示の更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime - totalPauseTime;
    if (pauseStartTime) {
      elapsed -= (now - pauseStartTime);
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    container.querySelector('#elapsed-time').textContent = 
      `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  }

  // 作業項目の読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#work-item');
    select.innerHTML = '<option value="">作業項目を選択してください</option>';

    if (workItems) {
      workItems
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          select.appendChild(option);
        });
    }
  }

  // 本日の作業履歴を表示
  async function renderTodayHistory() {
    const records = await window.aivicApi.list(1); // 作業記録
    const tbody = container.querySelector('#today-history');

    if (!records) {
      tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; padding: 20px; color: var(--text-muted);">データの読み込みに失敗しました</td></tr>';
      return;
    }

    const today = new Date().toDateString();
    const todayRecords = records.filter(record => {
      const recordDate = new Date(record.作業日).toDateString();
      return recordDate === today;
    });

    if (todayRecords.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; padding: 20px; color: var(--text-muted);">本日の作業履歴はありません</td></tr>';
      return;
    }

    tbody.innerHTML = todayRecords.map(record => {
      const startTime = new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}:${(record.作業時間 % 60).toString().padStart(2, '0')}` : '-';
      const statusColor = record.進捗状況 === '完了' ? '#22c55e' : record.進捗状況 === '作業中' ? '#3b82f6' : '#f59e0b';

      return `
        <tr>
          <td style="padding: 6px 8px;">${startTime}</td>
          <td style="padding: 6px 8px;">${record.作業種別 || '-'}</td>
          <td style="padding: 6px 8px;">${workTime}</td>
          <td style="padding: 6px 8px;"><span style="color: ${statusColor}; font-size: 11px;">${record.進捗状況}</span></td>
        </tr>
      `;
    }).join('');
  }

  // 作業開始
  container.querySelector('#btn-start').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item').value;
    if (!workItemId) {
      alert('作業項目を選択してください');
      return;
    }

    const workItems = await window.aivicApi.list(3);
    const selectedItem = workItems?.find(item => item.作業項目ID === workItemId);

    const newRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証されたユーザーIDを使用
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      プロジェクト名: selectedItem?.作業項目名|| '',
      作業場所: '現場A', // 実際の実装では選択可能にする
      作業種別: selectedItem?.作業項目名|| '',
      作業内容: '',
      進捗状況: '作業中',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, newRecord);
    if (saved) {
      currentWorkRecord = saved;
      startTime = new Date();
      totalPauseTime = 0;
      pauseStartTime = null;

      // ボタン状態更新
      container.querySelector('#btn-start').disabled = true;
      container.querySelector('#btn-end').disabled = false;
      container.querySelector('#btn-pause').disabled = false;
      container.querySelector('#work-item').disabled = true;

      // タイマー開始
      timerInterval = setInterval(updateElapsedTime, 1000);

      renderTodayHistory();
    }
  });

  // 作業終了
  container.querySelector('#btn-end').addEventListener('click', async () => {
    if (!currentWorkRecord) return;

    const endTime = new Date();
    let workTime = Math.floor((endTime - startTime - totalPauseTime) / (1000 * 60)); // 分単位
    if (pauseStartTime) {
      workTime -= Math.floor((endTime - pauseStartTime) / (1000 * 60));
    }

    const memo = container.querySelector('#work-memo').value;

    const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, {
      作業終了時刻: endTime.toISOString(),
      作業時間: workTime,
      作業内容: memo,
      進捗状況: '完了'
    });

    if (updated) {
      // 状態リセット
      currentWorkRecord = null;
      startTime = null;
      totalPauseTime = 0;
      pauseStartTime = null;
      clearInterval(timerInterval);

      // UI リセット
      container.querySelector('#btn-start').disabled = false;
      container.querySelector('#btn-end').disabled = true;
      container.querySelector('#btn-pause').disabled = true;
      container.querySelector('#work-item').disabled = false;
      container.querySelector('#work-item').value = '';
      container.querySelector('#work-memo').value = '';
      container.querySelector('#elapsed-time').textContent = '00:00:00';

      renderTodayHistory();
    }
  });

  // 中断
  container.querySelector('#btn-pause').addEventListener('click', () => {
    container.querySelector('#pause-reason-area').classList.remove('hidden');
  });

  // 中断確定
  container.querySelector('#btn-confirm-pause').addEventListener('click', async () => {
    const reason = container.querySelector('#pause-reason').value;
    const detail = container.querySelector('#pause-detail').value;

    if (!reason) {
      alert('中断理由を選択してください');
      return;
    }

    if (currentWorkRecord) {
      pauseStartTime = new Date();

      const pauseRecord = {
        作業記録ID: currentWorkRecord.作業記録ID,
        中断開始日時: pauseStartTime.toISOString(),
        中断理由区分: reason,
        中断理由詳細: detail,
        対応状況: '対応中',
        記録者ID: 'current-user-id'
      };

      await window.aivicApi.save(2, pauseRecord); // 中断記録
    }

    container.querySelector('#pause-reason-area').classList.add('hidden');
    container.querySelector('#pause-reason').value = '';
    container.querySelector('#pause-detail').value = '';
  });

  // 中断キャンセル
  container.querySelector('#btn-cancel-pause').addEventListener('click', () => {
    container.querySelector('#pause-reason-area').classList.add('hidden');
    container.querySelector('#pause-reason').value = '';
    container.querySelector('#pause-detail').value = '';
  });

  // 保存
  container.querySelector('#btn-save').addEventListener('click', async () => {
    if (!currentWorkRecord) return;

    const memo = container.querySelector('#work-memo').value;

    const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, {
      作業内容: memo
    });

    if (updated) {
      alert('作業メモを保存しました');
    }
  });

  // キャンセル
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (currentWorkRecord && confirm('作業中ですが、本当にキャンセルしますか？')) {
      // 作業記録を削除
      window.aivicApi.delete(1, currentWorkRecord.作業記録ID);

      // 状態リセット
      currentWorkRecord = null;
      startTime = null;
      totalPauseTime = 0;
      pauseStartTime = null;
      clearInterval(timerInterval);

      // UI リセット
      container.querySelector('#btn-start').disabled = false;
      container.querySelector('#btn-end').disabled = true;
      container.querySelector('#btn-pause').disabled = true;
      container.querySelector('#work-item').disabled = false;
      container.querySelector('#work-item').value = '';
      container.querySelector('#work-memo').value = '';
      container.querySelector('#elapsed-time').textContent = '00:00:00';

      renderTodayHistory();
    }
  });

  // 初期化
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);
  loadWorkItems();
  renderTodayHistory();
}
